// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // admissible domain: feeRate must be within the allowed cap so initialize succeeds
        feeRate = uint16(bound(feeRate, 0, 5_000));
        vm.assume(baseToken != address(0)); // nonzero base token is the domain where the rule bites

        c.initialize(
            baseToken,
            nft,
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after initialization, the pool's flash-fee token is the
        // base token that was configured (nonzero here). The mutant always sets
        // baseToken to address(0), so flashFeeToken() returns address(0).
        assertTrue(c.flashFeeToken() == baseToken);
    }
}
